WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) AS prev_paid_at FROM payments), with_gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessions_payments AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT s.id, s.order_id, s.amount, s.paid_at, s.is_new_session, s.session_id, (SELECT SUM(t2.cost) FROM shipments t2 WHERE t2.order_id = s.order_id) AS sum_shipment_cost FROM sessions_payments s ORDER BY amount DESC NULLS FIRST, is_new_session
